const raw = $input.first().json;
const body = raw?.body && typeof raw.body === 'object' ? raw.body : raw;

function t(value) { return String(value ?? '').trim(); }
const message = t(body.message);
const messageId = t(body.message_id) || `msg-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
const requestId = t(body.request_id) || `req-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
const conversationId = t(body.conversation_id) || 'powershell-local';
// 러너의 norm()과 같은 정규화. 이름만 있는 요청자의 신원 조각을 만들 때 쓴다.
const nk = (s) => t(s).toLowerCase().replace(/\s+/g, '');
const requesterRaw = body.requester && typeof body.requester === 'object' ? body.requester : {};
const requester = {
  email: t(requesterRaw.email ?? body.requester_email).toLowerCase(),
  name: t(requesterRaw.name ?? body.requester_name),
  teams_user_id: t(requesterRaw.teams_user_id ?? body.teams_user_id),
};
const context = body.context && typeof body.context === 'object' ? body.context : {};
const startedAtMs = Date.now();
const staticData = $getWorkflowStaticData('global');
const processed = staticData.processedMessages ?? {};
// 재전송을 걸러내는 열쇠는 '누가, 어느 대화에서, 어떤 메시지를' 보냈는가다.
// message_id 하나만 쓰면 다른 사람이 같은 id를 보냈을 때 남의 응답과 대화 문맥이 그대로 돌아간다.
// 신원 조각은 러너의 requester_state_key와 **같은 순서로 같은 값**을 봐야 한다
// (assistant.py: clean_email(email) or teams_user_id or norm(name)).
// 이메일 없이 이름만 있는 요청자도 게이트를 통과하는데, 여기서 이름을 안 보면 그런 사람이
// 전부 'anonymous' 한 칸에 몰린다. 그러면 같은 대화·같은 message_id를 쓴 다른 사람에게
// 남의 티켓 제목·Notion URL·대화 문맥이 duplicate:true로 그대로 돌아간다.
const identity = requester.email || requester.teams_user_id || nk(requester.name) || 'anonymous';
const dedupeKey = [identity, conversationId, messageId].join('|');

if (processed[dedupeKey]) {
  return [{ json: {
    dedupe_key: dedupeKey,
    local_handled: true,
    message_id: messageId,
    request_id: requestId,
    conversation_id: conversationId,
    started_at_ms: startedAtMs,
    local_response: {
      ...processed[dedupeKey],
      _stored_at_ms: undefined,
      action: processed[dedupeKey].action ?? 'DUPLICATE_MESSAGE',
      duplicate: true,
      message_id: messageId,
      request_id: requestId,
      conversation_id: conversationId,
    },
  }}];
}

if (!message) {
  return [{ json: {
    dedupe_key: dedupeKey,
    local_handled: true,
    message_id: messageId,
    request_id: requestId,
    conversation_id: conversationId,
    started_at_ms: startedAtMs,
    local_response: {
      action: 'NEED_INPUT',
      response_text: '요청 내용을 입력해주세요.',
      context,
      message_id: messageId,
      request_id: requestId,
      conversation_id: conversationId,
    },
  }}];
}

if (message.includes('\uFFFD') || /\?{3,}/.test(message)) {
  return [{ json: {
    dedupe_key: dedupeKey,
    local_handled: true,
    message_id: messageId,
    request_id: requestId,
    conversation_id: conversationId,
    started_at_ms: startedAtMs,
    local_response: {
      action: 'INVALID_TEXT_ENCODING',
      response_text: '한글 입력이 깨졌습니다. UTF-8로 다시 전송해주세요.',
      context,
      message_id: messageId,
      request_id: requestId,
      conversation_id: conversationId,
    },
  }}];
}

if (!requester.email && !requester.name) {
  return [{ json: {
    dedupe_key: dedupeKey,
    local_handled: true,
    message_id: messageId,
    request_id: requestId,
    conversation_id: conversationId,
    started_at_ms: startedAtMs,
    local_response: {
      action: 'NEED_REQUESTER',
      response_text: '요청자 이메일 또는 이름이 필요합니다. Teams 연동 시에는 메시지 발신자 정보에서 자동으로 전달해야 합니다.',
      context,
      message_id: messageId,
      request_id: requestId,
      conversation_id: conversationId,
    },
  }}];
}

return [{ json: {
  dedupe_key: dedupeKey,
  local_handled: false,
  message,
  attachments: Array.isArray(body.attachments) ? body.attachments.slice(0, 3) : [],
  message_id: messageId,
  request_id: requestId,
  conversation_id: conversationId,
  requester,
  context,
  started_at_ms: startedAtMs,
}}];

const prepared = $('요청 전처리').first().json;
return [{ json: {
  ...prepared.local_response,
  dedupe_key: prepared.dedupe_key,
  message_id: prepared.message_id,
  request_id: prepared.request_id,
  conversation_id: prepared.conversation_id,
  timing: { total_ms: Date.now() - prepared.started_at_ms, assistant_ms: 0, ai_ms: 0, local: true },
}}];

const src = $input.first().json;
const prepared = $('요청 전처리').first().json;
const staticData = $getWorkflowStaticData('global');
const cache = staticData.workDataCache || {};
const projects = Array.isArray(src.projects) ? src.projects : (Array.isArray(cache.projects) ? cache.projects : []);
const tickets = Array.isArray(src.tickets) ? src.tickets : (Array.isArray(cache.tickets) ? cache.tickets : []);
const workSchema = src.work_schema ?? cache.work_schema ?? {};
return [{ json: {
  request_id: prepared.request_id,
  message_id: prepared.message_id,
  dedupe_key: prepared.dedupe_key,
  conversation_id: prepared.conversation_id,
  message: prepared.message,
  attachments: Array.isArray(prepared.attachments) ? prepared.attachments : [],
  requester: prepared.requester,
  context: prepared.context,
  projects,
  tickets,
  work_schema: workSchema,
  started_at_ms: prepared.started_at_ms,
}}];

const assistant = $input.first().json;
const payload = $('AI 요청 구성').first().json;
if (assistant?.ok !== true || !assistant?.data) {
  const detail = assistant?.error?.message ?? assistant?.message ?? assistant?.error ?? '응답 없음';
  return [{ json: {
    action: 'ASSISTANT_ERROR',
    response_text: `업무 도우미 처리 중 오류가 발생했습니다. 진행 중인 작업과 이전 대화 내용은 유지했습니다.\n오류: ${String(detail)}`,
    context: payload.context ?? {},
    needs_write: false,
    message_id: payload.message_id,
    dedupe_key: payload.dedupe_key,
    request_id: payload.request_id,
    conversation_id: payload.conversation_id,
    started_at_ms: payload.started_at_ms,
    assistant_meta: assistant?.meta ?? {},
    detail: assistant,
  }}];
}
const data = assistant.data;
const write = data.write_request && typeof data.write_request === 'object' ? data.write_request : null;
return [{ json: {
  ...data,
  needs_write: Boolean(write),
  write_kind: write?.kind ?? '',
  write_body: write?.body ?? null,
  write_page_id: write?.page_id ?? '',
  message_id: payload.message_id,
  dedupe_key: payload.dedupe_key,
  request_id: payload.request_id,
  conversation_id: payload.conversation_id,
  started_at_ms: payload.started_at_ms,
  assistant_meta: assistant.meta ?? {},
}}];

const value = $input.first().json;
return [{ json: {
  action: value.action,
  response_text: value.response_text,
  context: value.context ?? {},
  questions: value.questions ?? [],
  tickets: value.tickets ?? [],
  projects: value.projects ?? [],
  total: value.total,
  ticket: value.ticket,
  ticket_draft: value.ticket_draft,
  changes: value.changes,
  // 러너가 내보내는데 여기서 떨어뜨리고 있던 두 필드다.
  // choices가 빠져서 원탭 선택 버튼이 화면에 아예 나오지 않았고,
  // start_index가 빠져서 카드 번호가 2페이지부터 본문과 어긋났다.
  // 이 노드는 허용목록이라, 러너에 필드를 더할 때 여기도 같이 손대야 한다.
  choices: value.choices ?? [],
  start_index: value.start_index,
  dedupe_key: value.dedupe_key,
  message_id: value.message_id,
  request_id: value.request_id,
  conversation_id: value.conversation_id,
  timing: {
    total_ms: Date.now() - Number(value.started_at_ms ?? Date.now()),
    assistant_ms: Number(value.assistant_meta?.duration_ms ?? 0),
    ai_ms: Number(value.assistant_meta?.ai_ms ?? 0),
    ai_used: value.assistant_meta?.ai_used === true,
    local: value.assistant_meta?.ai_used !== true,
  },
}}];

const notion = $input.first().json;
const decision = $('업무 해석 결과').first().json;
const context = decision.context && typeof decision.context === 'object' ? { ...decision.context } : {};
const pending = context.pending_action && typeof context.pending_action === 'object' ? { ...context.pending_action } : {};
const now = new Date().toISOString();
const notionError = notion?.error?.message ?? notion?.error ?? notion?.message;
const success = Boolean(notion?.id) && !notionError;

if (!success) {
  const title = pending.ticket_title ?? context.ticket_draft?.title ?? context.selected_ticket?.title ?? '티켓';
  context.pending_action = pending;
  context.pending_question = pending.kind === 'UPDATE' ? 'write_retry' : 'approval';
  context.last_action = {
    kind: decision.write_kind || pending.kind || 'WRITE',
    success: false,
    ticket_id: pending.ticket_id ?? '',
    ticket_title: title,
    changes: pending.changes ?? {},
    error: String(notionError ?? 'Notion 응답에 페이지 ID가 없습니다.'),
    at: now,
  };
  context._context_revision = Number(context._context_revision ?? 0) + 1;
  context._context_updated_at = now;
  const retryText = pending.kind === 'UPDATE'
    ? '변경 요청을 유지했습니다.'
    : '승인 대기 중인 티켓 초안을 유지했습니다.';
  return [{ json: {
    action: 'WRITE_ERROR',
    response_text: `Notion 반영 중 오류가 발생했습니다. ${retryText}\n오류: ${context.last_action.error}\n다시 시도하려면 '재시도', 중단하려면 '아니요'라고 입력해주세요.`,
    context,
    ticket: context.selected_ticket ?? null,
    message_id: decision.message_id,
    request_id: decision.request_id,
    conversation_id: decision.conversation_id,
    timing: {
      total_ms: Date.now() - Number(decision.started_at_ms ?? Date.now()),
      assistant_ms: Number(decision.assistant_meta?.duration_ms ?? 0),
      ai_ms: Number(decision.assistant_meta?.ai_ms ?? 0),
      ai_used: decision.assistant_meta?.ai_used === true,
      local: decision.assistant_meta?.ai_used !== true,
    },
  }}];
}

// Notion 자기-쓰기 성공 → 캐시 무효화(다음 조회가 최신 반영)
delete $getWorkflowStaticData('global').workDataCache;
delete context.pending_action;
delete context.pending_question;
let action;
let responseText;
let ticket;

if (decision.write_kind === 'COMMENT') {
  action = 'COMMENTED';
  const title = pending.ticket_title ?? context.selected_ticket?.title ?? '티켓';
  responseText = `'${title}' 티켓에 댓글을 남겼습니다.`;
  ticket = context.selected_ticket ?? null;
  context.last_action = { kind: 'COMMENT', success: true, ticket_id: pending.ticket_id ?? '', ticket_title: title, at: now };
} else if (decision.write_kind === 'CREATE') {
  action = 'CREATED';
  const title = context.ticket_draft?.title ?? '제목 없음';
  responseText = `Notion 티켓이 생성됐습니다.\n제목: ${title}\n링크: ${notion.url ?? ''}`;
  ticket = {
    id: notion.id,
    title,
    url: notion.url ?? '',
    status: context.status ?? '계획',
    due_date: context.due_date ?? '',
    priority: context.priority ?? '',
    difficulty: context.difficulty ?? '',
  };
  context.selected_ticket = ticket;
  context.last_results = notion.id ? [notion.id] : [];
  context.last_result_start = 1;
  context.last_action = {
    kind: 'CREATE', success: true, ticket_id: notion.id ?? '', ticket_title: title,
    url: notion.url ?? '', at: now,
  };
  // 초안이 티켓이 되면 그 초안에 딸린 것도 함께 끝난다 — CREATE에서만 닫는다.
  // 이 삭제가 분기 밖에 있으면 COMMENT·UPDATE 성공도 지워, 승인 대기 중이던 초안의
  // ticket_draft·draft_images와 이미지 Q&A가 참조하는 image_notes가 통째로 사라진다.
  // 러너는 초안을 만들 때 draft_images에 '이 초안이 보고 쓴 화면'을 적어 두는데,
  // 소진된 뒤에도 남아 있으면 다음 초안이 그것을 이어받는다.
  delete context.draft_images;
  delete context.ticket_draft;
  delete context.image_notes;
} else {
  action = 'UPDATED';
  // 실제 저장된 페이지 객체에서 적용 값을 읽어 표시한다(§9.3 실행 후 확인).
  const applied = [];
  try {
    const props = notion.properties ?? {};
    const pick = (name) => {
      const pr = props[name];
      if (!pr) return null;
      if (pr.status) return pr.status?.name ?? null;
      if (pr.select) return pr.select?.name ?? null;
      if (pr.date) return pr.date?.start ?? null;
      if (pr.title) return (pr.title[0]?.plain_text ?? null);
      return null;
    };
    const label = { '진행상태': '진행상태', '마감일': '마감일', '시작일': '시작일', '우선순위': '우선순위', '난이도': '난이도', '제목': '제목' };
    for (const k of Object.keys(label)) {
      const v = pick(k);
      if (v !== null && v !== undefined) applied.push(`${label[k]}: ${v}`);
    }
  } catch (e) { /* 표시용 — 실패해도 본 응답은 유지 */ }
  context._applied_line = applied.length ? `적용된 값 — ${applied.join(' / ')}` : '';
  const title = pending.ticket_title ?? context.selected_ticket?.title ?? '티켓';
  const changes = pending.changes && typeof pending.changes === 'object' ? pending.changes : {};
  const selected = context.selected_ticket && typeof context.selected_ticket === 'object' ? { ...context.selected_ticket } : {};
  ticket = { ...selected, id: notion.id ?? pending.ticket_id, title, url: notion.url ?? selected.url ?? '' };
  if (Object.prototype.hasOwnProperty.call(changes, 'status')) ticket.status = changes.status;
  if (Object.prototype.hasOwnProperty.call(changes, 'due_date')) ticket.due_date = changes.due_date;
  if (Object.prototype.hasOwnProperty.call(changes, 'priority')) ticket.priority = changes.priority;
  if (Object.prototype.hasOwnProperty.call(changes, 'difficulty')) ticket.difficulty = changes.difficulty;
  if (Object.prototype.hasOwnProperty.call(changes, 'assignee_ids')) {
    ticket.assignees = Array.isArray(pending.assignee_people) ? pending.assignee_people : [];
  }
  context.selected_ticket = ticket;
  context.last_action = {
    kind: 'UPDATE', success: true, ticket_id: ticket.id ?? pending.ticket_id ?? '', ticket_title: title,
    url: ticket.url ?? '', changes, at: now,
  };
  const labels = { status: '진행상태', due_date: '마감일', priority: '우선순위', difficulty: '난이도', assignee_ids: '티켓 담당자' };
  const detailLines = Object.entries(changes).map(([key, value]) => {
    if (key === 'assignee_ids') {
      const people = Array.isArray(pending.assignee_people) ? pending.assignee_people : [];
      const display = people.map((person) => person?.name || person?.email || person?.id).filter(Boolean).join(', ') || '미할당';
      return `- ${labels[key]}: ${display}`;
    }
    return `- ${labels[key] ?? key}: ${value || '없음'}`;
  });
  responseText = `'${title}' 티켓을 변경했습니다.`;
  if (detailLines.length) responseText += `\n${detailLines.join('\n')}`;
  if (context._applied_line) { responseText += String.fromCharCode(10) + context._applied_line; }
  delete context._applied_line;
  if (ticket.url) responseText += `\n링크: ${ticket.url}`;
}

context._context_revision = Number(context._context_revision ?? 0) + 1;
context._context_updated_at = now;
return [{ json: {
  action, response_text: responseText, context, ticket,
  // 이 경로는 Notion에 쓴 뒤다. 재전송이 오면 다시 쓰지 않도록 응답을 기억해 둔다.
  _dedupe_worthy: true,
  choices: decision.choices ?? [],
  message_id: decision.message_id, dedupe_key: decision.dedupe_key,
  request_id: decision.request_id, conversation_id: decision.conversation_id,
  timing: {
    total_ms: Date.now() - Number(decision.started_at_ms ?? Date.now()),
    assistant_ms: Number(decision.assistant_meta?.duration_ms ?? 0),
    ai_ms: Number(decision.assistant_meta?.ai_ms ?? 0),
    ai_used: decision.assistant_meta?.ai_used === true,
    local: decision.assistant_meta?.ai_used !== true,
  },
}}];

// 재전송 판별에 필요한 기간은 워커가 다시 보내는 몇 분이다. 이 표는 워크플로 정적 데이터에
// 남고, 그 정적 데이터는 하나의 덩어리라 여기에 쓸 때마다 같은 덩어리에 든 조회 캐시(원본
// Notion 페이지 전부)까지 함께 다시 직렬화된다. 그래서 작게 유지한다.
const RETENTION_MS = 60 * 60 * 1000;
const MAX_ENTRIES = 60;

const value = $input.first().json;
const staticData = $getWorkflowStaticData('global');
const processed = staticData.processedMessages ?? {};
// 재전송을 걸러내는 열쇠는 '누가, 어느 대화에서, 어떤 메시지를' 보냈는가다. 전처리 노드가 만든 값을 그대로 쓴다.
// message_id 하나로 저장하면 다른 사람이 같은 id를 보냈을 때 남의 응답과 대화 문맥이 돌아간다.
const { dedupe_key: dedupeKey, _dedupe_worthy: worthy, ...response } = value;
const key = dedupeKey || value.message_id;
// 쓰기 응답만 기억한다. 조회까지 기억하면 조회 한 번에 정적 데이터 전체가 다시 저장된다.
if (key && worthy) {
  processed[key] = { ...response, _stored_at_ms: Date.now() };
  // 오래된 항목부터 정리한다. 이 표는 워크플로 정적 데이터에 그대로 쌓인다.
  const cutoff = Date.now() - RETENTION_MS;
  for (const [k, v] of Object.entries(processed)) {
    if (typeof v?._stored_at_ms === 'number' && v._stored_at_ms < cutoff) delete processed[k];
  }
  const keys = Object.keys(processed);
  if (keys.length > MAX_ENTRIES) {
    for (const k of keys.slice(0, keys.length - MAX_ENTRIES)) delete processed[k];
  }
  staticData.processedMessages = processed;
}
return [{ json: response }];

const result = { ...$('Notion 변경 결과').first().json };
const sync = $input.first().json;
if (sync?.error) {
  // 사용자에게 보이는 곳에 적는다. 필드에만 넣어 두면 아무도 읽지 않아 조용히 사라진다.
  // Notion 반영은 끝났으므로 실패라고 말하면 안 되고, 이어지는 대화가 이 변경을 모를 수
  // 있다는 것이 실제로 사용자에게 미치는 영향이다.
  result.state_sync_warning = '서버 대화 상태 저장에 실패했습니다.';
  result.response_text = [
    result.response_text,
    'Notion 반영은 끝났지만 대화 내용 저장에 실패했습니다. 이어지는 질문에서 이 변경이 보이지 않으면 다시 조회해 주세요.',
  ].filter(Boolean).join('\n');
}
return [{ json: result }];

const prepared = $('요청 전처리').first().json;
const TTL_MS = 5 * 60 * 1000;
const staticData = $getWorkflowStaticData('global');
const cache = staticData.workDataCache;
const now = Date.now();
const cacheHit = !!(
  cache && typeof cache === 'object' &&
  Array.isArray(cache.projects) && cache.projects.length > 0 &&
  Array.isArray(cache.tickets) && cache.tickets.length > 0 &&
  cache.work_schema !== undefined && cache.work_schema !== null &&
  (now - Number(cache.ts || 0) < TTL_MS)
);
return [{ json: { ...prepared, cache_hit: cacheHit } }];

const projects = $('프로젝트 묶기').first().json.projects ?? [];
const tickets = $('작업 묶기').first().json.tickets ?? [];
const workSchema = $input.first().json;
const staticData = $getWorkflowStaticData('global');
// 적중 판정('캐시 확인')은 projects·tickets가 **둘 다** 있어야 캐시를 쓴다(AND). 저장도
// 같은 술어여야 한다 — OR로 저장하면 한쪽만 있는 데이터가 캐시에 남아도 영영 못 읽혀
// 매 요청이 Notion 전체를 다시 조회한다. 완전한 데이터일 때만 캐시한다(실패한 조회가
// alwaysOutputData로 돌려주는 빈 배열도 이 조건이 함께 막는다).
if (projects.length > 0 && tickets.length > 0) {
  staticData.workDataCache = { projects, tickets, work_schema: workSchema, ts: Date.now() };
}
return [{ json: { projects, tickets, work_schema: workSchema } }];

const created = $input.first().json;
if (!created || created.object !== 'page' || !created.id) { return []; }
const result = $('업무 해석 결과').first().json;
// 붙일 사진은 '이 초안이 보고 쓴 화면'이다. 이 노드는 승인 턴('등록해줘')에 실행되므로
// 이번 메시지에는 사진이 없다. 러너가 초안을 만들 때 context.draft_images에 적어 둔다.
// 대화 폴더를 통째로 훑던 예전 방식은 지난 턴 스크린샷을 새 티켓에 붙였다.
const context = result?.context ?? {};
let files = Array.isArray(context.draft_images) ? context.draft_images.filter(Boolean) : [];
if (!files.length) {
  // 옛 대화에서 넘어온 문맥이라 draft_images가 없을 수 있다. 그때는 가장 최근에 보여준 사진.
  const notes = Array.isArray(context.image_notes) ? context.image_notes : [];
  const note = [...notes].reverse().find((n) => Array.isArray(n?.stored_files) && n.stored_files.length);
  files = note ? note.stored_files.filter(Boolean) : [];
}
if (!files.length) { return []; }
const conv = String($('AI 요청 구성').first().json.conversation_id ?? '');
const key = conv.replace(/[^A-Za-z0-9_-]/g, '').slice(0, 64) || 'unknown';
const dir = '/home/n8n/.n8n-files/clovirone-work-assistant-images/' + key;
return files.slice(0, 3).map((name) => ({
  json: { page_id: created.id, glob: dir + '/' + String(name).replace(/[^A-Za-z0-9._-]/g, '') },
}));
